script:
(function () {
  'use strict';
  // Surviving spouse (sole beneficiary) of an inherited traditional IRA: projects the four options
  // side by side, year by year. RMD = prior Dec 31 balance / divisor; next balance =
  // balance x (1 + return) - withdrawal (same convention as the RMD calculator).
  //   Treat as your own: Uniform Lifetime Table at your age, from the year you reach your own RMD
  //     age (or the year after the death if later).
  //   Remain a beneficiary (Single Life Table): divisor = Table I at your age, looked up again each
  //     year. Owner died before the required beginning date (RBD): first RMD in the later of the
  //     year after death and the year the owner would have reached RMD age. Died on/after RBD:
  //     first RMD the year after death, divisor = larger of your Table I value and the owner's
  //     remaining life expectancy (Table I at owner's age in year of death, minus 1 per year).
  //   Spousal election, IRC 401(a)(9)(B)(iv): same timing, Uniform Lifetime Table at your age
  //     (proposed Treas. Reg. 1.401(a)(9)-5(g)(3)(ii)); only if the first RMD year is 2024 or later.
  //   10-year rule (owner died before RBD only): nothing required until the whole balance is
  //     paid out by Dec 31 of the 10th year after death.
  // Checked in Node (scratch tests): Pub. 590-B examples Table I age 57 = 29.8, age 55 = 31.6;
  // Table III age 75 = 24.6. Owner born 1964-03-12, died 2025-08-01, spouse born 1968-11-05,
  // $500,000 on Dec 31 2025, 5%: own RMDs start 2043 (age 75); beneficiary RMDs start 2039
  // (owner would be 75, spouse 71): 2039 balance 500,000 x 1.05^13 = 942,824.66 -> / 18.0 =
  // 52,379.14 (Table I) and / 28.3 = 33,315.36 (Uniform); 10-year payout in 2035 =
  // 500,000 x 1.05^10 = 814,447.31; 59 1/2 on May 5, 2028. After-RBD case: owner born 1950-02-01,
  // died 2024-05-01 (RBD April 1, 2023), spouse born 1952, $500,000: 2026 Table I(74) 15.6 vs owner
  // 15.6 - 2 = 13.6 -> 32,051.28; election max(Uniform 25.5, 13.6) -> 19,607.84; a spouse born 1940
  // gets the owner's 13.6 -> 36,764.71. Election blocked when the first RMD year is before 2024.
  //
  // ---- IRS life expectancy tables (distribution years 2022 and later; used for 2026) -------
  // SINGLE_LIFE: IRS Pub. 590-B (2025), Appendix B, Table I (Treas. Reg. 1.401(a)(9)-9(b)), ages 0-120+.
  // UNIFORM: Treas. Reg. 1.401(a)(9)-9(c) Uniform Lifetime Table as republished for ages 10-120+
  //   in proposed regs REG-103529-23 (89 FR 58644, July 19, 2024); ages 72+ match Pub. 590-B Table III.
  // Every value was compared programmatically with the IRS text.
  var SINGLE_LIFE = [
    84.6, 83.7, 82.8, 81.8, 80.8, 79.8, 78.8, 77.9, 76.9, 75.9, 74.9, 73.9, 72.9, 71.9, 70.9,
    69.9, 69.0, 68.0, 67.0, 66.0, 65.0, 64.1, 63.1, 62.1, 61.1, 60.2, 59.2, 58.2, 57.3, 56.3,
    55.3, 54.4, 53.4, 52.5, 51.5, 50.5, 49.6, 48.6, 47.7, 46.7, 45.7, 44.8, 43.8, 42.9, 41.9,
    41.0, 40.0, 39.0, 38.1, 37.1, 36.2, 35.3, 34.3, 33.4, 32.5, 31.6, 30.6, 29.8, 28.9, 28.0,
    27.1, 26.2, 25.4, 24.5, 23.7, 22.9, 22.0, 21.2, 20.4, 19.6, 18.8, 18.0, 17.2, 16.4, 15.6,
    14.8, 14.1, 13.3, 12.6, 11.9, 11.2, 10.5, 9.9, 9.3, 8.7, 8.1, 7.6, 7.1, 6.6, 6.1,
    5.7, 5.3, 4.9, 4.6, 4.3, 4.0, 3.7, 3.4, 3.2, 3.0, 2.8, 2.6, 2.5, 2.3, 2.2,
    2.1, 2.1, 2.1, 2.0, 2.0, 2.0, 2.0, 2.0, 1.9, 1.9, 1.8, 1.8, 1.6, 1.4, 1.1,
    1.0
  ];
  var UNIFORM = [
    88.2, 87.2, 86.2, 85.2, 84.2, 83.2, 82.2, 81.2, 80.2, 79.2, 78.2, 77.2, 76.2, 75.2, 74.2,
    73.3, 72.3, 71.3, 70.3, 69.3, 68.3, 67.3, 66.3, 65.3, 64.3, 63.3, 62.3, 61.3, 60.3, 59.4,
    58.4, 57.4, 56.4, 55.4, 54.4, 53.4, 52.4, 51.5, 50.5, 49.5, 48.5, 47.5, 46.5, 45.6, 44.6,
    43.6, 42.6, 41.6, 40.7, 39.7, 38.7, 37.7, 36.8, 35.8, 34.9, 33.9, 33.0, 32.0, 31.1, 30.1,
    29.2, 28.3, 27.4, 26.5, 25.5, 24.6, 23.7, 22.9, 22.0, 21.1, 20.2, 19.4, 18.5, 17.7, 16.8,
    16.0, 15.2, 14.4, 13.7, 12.9, 12.2, 11.5, 10.8, 10.1, 9.5, 8.9, 8.4, 7.8, 7.3, 6.8,
    6.4, 6.0, 5.6, 5.2, 4.9, 4.6, 4.3, 4.1, 3.9, 3.7, 3.5, 3.4, 3.3, 3.1, 3.0,
    2.9, 2.8, 2.7, 2.5, 2.3, 2.0
  ]; // index 0 = age 10
  // RMD age (SECURE Act 2019, SECURE 2.0 Act 2022): born before July 1, 1949: 70 1/2;
  // July 1, 1949-1950: 72; 1951-1959: 73; 1960 or later: 75. RBD = April 1 of the next year.
  // The 401(a)(9)(B)(iv) spousal election applies only if the first RMD year is 2024 or later.
  var ELECTION_FIRST_YEAR = 2024;
  // ------------------------------------------------------------------------------------------

  function singleLife(age) { return SINGLE_LIFE[Math.max(0, Math.min(120, age))]; }
  function uniform(age) { return UNIFORM[Math.max(10, Math.min(120, age)) - 10]; }

  function parseDate(s) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s || '');
    if (!m) return null;
    var d = { y: +m[1], m: +m[2], d: +m[3], iso: s };
    return d.m >= 1 && d.m <= 12 && d.d >= 1 && d.d <= 31 ? d : null;
  }
  // Year the owner reaches RMD age and that age's label.
  function rmdStart(dob) {
    if (dob.y < 1949 || (dob.y === 1949 && dob.m < 7)) {
      return { label: '70½', year: dob.y + 70 + (dob.m >= 7 ? 1 : 0) };
    }
    var a = dob.y <= 1950 ? 72 : dob.y <= 1959 ? 73 : 75;
    return { label: String(a), year: dob.y + a };
  }
  function addHalfYear(dob, years) {
    var y = dob.y + years, m = dob.m + 6;
    if (m > 12) { m -= 12; y++; }
    var dim = new Date(Date.UTC(y, m, 0)).getUTCDate();
    return { y: y, m: m, d: Math.min(dob.d, dim) };
  }
  var MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September',
                'October', 'November', 'December'];
  function longDate(x) { return MONTHS[x.m - 1] + ' ' + x.d + ', ' + x.y; }

  // Works out each option's rules from the dates.
  function rules(owner, death, spouse) {
    var os = rmdStart(owner), ss = rmdStart(spouse);
    var rbd = (os.year + 1) + '-04-01';
    var beforeRbd = death.iso < rbd;
    var D = death.y;
    var benFirst = beforeRbd ? Math.max(D + 1, os.year) : D + 1;
    var ownerAgeAtDeath = D - owner.y;
    function ownerRemaining(y) { return beforeRbd ? 0 : singleLife(ownerAgeAtDeath) - (y - D); }
    return {
      ownerStart: os, spouseStart: ss, rbd: rbd, beforeRbd: beforeRbd, deathYear: D,
      ownFirst: Math.max(D + 1, ss.year), benFirst: benFirst,
      electionAllowed: benFirst >= ELECTION_FIRST_YEAR,
      tenYearAllowed: beforeRbd, tenYearDeadline: D + 10,
      divisor: function (opt, y) {
        var age = y - spouse.y;
        if (opt === 'own') return uniform(age);
        if (opt === 'ben') return Math.max(singleLife(age), ownerRemaining(y));
        if (opt === 'elect') return Math.max(uniform(age), ownerRemaining(y));
        return 0;
      }
    };
  }

  // Projects one option from startYear to endYear. Returns yearly withdrawals and totals.
  function project(opt, r, startYear, endYear, balance, rate) {
    var b = balance, rows = [], total = 0;
    var first = opt === 'own' ? r.ownFirst : opt === 'ten' ? r.tenYearDeadline : r.benFirst;
    var firstAmount = null;
    for (var y = startYear; y <= endYear; y++) {
      var w = 0, div = 0;
      if (opt === 'ten') {
        if (y === r.tenYearDeadline) w = b * (1 + rate);
      } else if (y >= first) {
        div = r.divisor(opt, y);
        w = div > 1 ? b / div : b;
        w = Math.min(w, b);
      }
      if (firstAmount === null && y === first) firstAmount = w;
      total += w;
      rows.push({ year: y, start: b, divisor: div, rmd: w });
      b = Math.max(0, b * (1 + rate) - w);
      if (b < 0.005) b = 0;
    }
    return { rows: rows, total: total, end: b, first: first, firstAmount: firstAmount };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  function money(x) { return moneyFmt.format(Math.abs(x) < 0.005 ? 0 : x); }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function cell(tr, text, tag) { var c = document.createElement(tag || 'td'); c.textContent = text; tr.appendChild(c); }

  function clear() {
    ['spRbd', 'spBenStart', 'spOwnStart', 'spHalf'].forEach(function (id) { set(id, '–'); });
    document.getElementById('spSummary').textContent = '';
    document.getElementById('spSchedule').textContent = '';
    set('spNote', '');
  }

  function update() {
    var owner = parseDate(document.getElementById('spOwnerDob').value),
        death = parseDate(document.getElementById('spDeath').value),
        spouse = parseDate(document.getElementById('spSpouseDob').value),
        balance = num('spBalance'), rate = num('spRate'), startYear = Math.round(num('spStart')),
        thru = Math.round(num('spThru'));
    var error = document.getElementById('spError');
    var msg = '';
    if (!owner || !death || !spouse) msg = 'Enter all three dates.';
    else if (death.y < 2020 || death.y > 2100) msg = 'This calculator covers deaths in 2020 or later (SECURE Act rules).';
    else if (death.iso <= owner.iso) msg = 'The date of death must be after the owner’s date of birth.';
    else if (spouse.y < 1900 || spouse.y > death.y) msg = 'Enter a valid date of birth for the surviving spouse.';
    else if ([balance, rate, startYear, thru].some(isNaN) || balance < 0 || rate < -50 || rate > 30)
      msg = 'Enter a non-negative balance and a return from -50% to 30%.';
    else if (startYear < 2020 || startYear > 2100) msg = 'Enter a projection start year from 2020 to 2100.';
    else if (thru < 60 || thru > 120) msg = 'Project through an age from 60 to 120.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clear(); return; }

    var r = rules(owner, death, spouse);
    var first = Math.max(startYear, r.deathYear + 1);
    var endYear = Math.max(first, spouse.y + thru);
    if (endYear - first > 80) endYear = first + 80;
    rate = rate / 100;
    // Balance entered is Dec 31 of (startYear - 1); grow it to Dec 31 of (first - 1) if needed.
    var b0 = balance * Math.pow(1 + rate, first - startYear);
    var half = addHalfYear(spouse, 59);

    set('spBalYear', String(startYear - 1));
    set('spRbd', r.beforeRbd ? 'Before (RBD ' + longDate(parseDate(r.rbd)) + ')' : 'On or after (RBD ' + longDate(parseDate(r.rbd)) + ')');
    set('spBenStart', String(r.benFirst));
    set('spOwnStart', r.spouseStart.label + ' (' + r.ownFirst + ')');
    set('spHalf', longDate(half));

    var opts = [
      { key: 'own', name: 'Treat as your own IRA', ok: true },
      { key: 'ben', name: 'Remain a beneficiary (Single Life Table)', ok: true },
      { key: 'elect', name: 'Spousal election (Uniform Lifetime Table)', ok: r.electionAllowed },
      { key: 'ten', name: '10-year rule', ok: r.tenYearAllowed && first <= r.tenYearDeadline }
    ];
    var results = {};
    opts.forEach(function (o) { if (o.ok) results[o.key] = project(o.key, r, first, endYear, b0, rate); });

    var halfIso = half.y + '-' + (half.m < 10 ? '0' : '') + half.m + '-' + (half.d < 10 ? '0' : '') + half.d;
    var penaltyOwn = (first + '-12-31') < halfIso
      ? 'Yes, on withdrawals before ' + longDate(half) : 'No (you are past 59½)';
    var summary = document.getElementById('spSummary');
    summary.textContent = '';
    opts.forEach(function (o) {
      var tr = document.createElement('tr');
      cell(tr, o.name, 'th');
      var p = results[o.key];
      if (!p) {
        var why = o.key === 'elect' ? 'Not available: first RMD year was before 2024'
          : r.tenYearAllowed ? 'Deadline (' + r.tenYearDeadline + ') has passed' : 'Not available: owner died on or after the RBD';
        cell(tr, why); cell(tr, '–'); cell(tr, '–'); cell(tr, '–'); cell(tr, '–');
      } else {
        cell(tr, o.key === 'ten' ? 'Full payout in ' + p.first : p.first + ' (age ' + (p.first - spouse.y) + ')');
        cell(tr, p.firstAmount === null ? 'Before projection' : money(p.firstAmount));
        cell(tr, money(p.total));
        cell(tr, money(p.end));
        cell(tr, o.key === 'own' ? penaltyOwn : 'No (death exception)');
      }
      summary.appendChild(tr);
    });

    var body = document.getElementById('spSchedule');
    body.textContent = '';
    for (var i = 0; i <= endYear - first; i++) {
      var y = first + i, tr = document.createElement('tr');
      cell(tr, String(y)); cell(tr, String(y - spouse.y));
      ['own', 'ben', 'elect', 'ten'].forEach(function (k) {
        var p = results[k];
        cell(tr, p ? money(p.rows[i].rmd) : '–');
      });
      body.appendChild(tr);
    }

    var notes = [];
    if (first > startYear) notes.push('Beneficiary distributions start in ' + first + ', so the balance you entered is grown at the assumed return to December 31, ' + (first - 1) + '.');
    if (!r.beforeRbd && first === r.deathYear + 1) notes.push('The owner died on or after the RBD, so the owner’s own RMD for ' + r.deathYear + ' had to be taken by December 31, ' + r.deathYear + ' if they had not already taken it.');
    set('spNote', notes.join(' '));
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('spForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
